#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
영상 생성 고치기  (더블클릭 한 번)

깃허브 서버의 한글 폰트 패키지 구성이 바뀌어서 영상 생성이 실패했습니다.
경로를 고정하지 않고 찾아서 쓰도록 바꿉니다.

이 파일은 저장소 폴더(= queue.csv 가 있는 폴더) 안에 두고 실행하세요.
"""

import base64, os, subprocess

ROOT = os.path.dirname(os.path.abspath(__file__))
PAYLOAD = {'.github/workflows/weekly-content.yml': '',
 'make_reel.py': ''}


def run(*a):
    return subprocess.run(a, cwd=ROOT, stdout=subprocess.PIPE,
                          stderr=subprocess.STDOUT)


def out(p):
    return p.stdout.decode("utf-8", "replace").strip()


def main():
    print("영상 생성 고치기")
    print("폴더:", ROOT)
    print()

    if not os.path.exists(os.path.join(ROOT, "queue.csv")):
        print("!! queue.csv 가 있는 폴더에 두고 실행하세요.")
        input("\n엔터를 누르면 닫힙니다...")
        return

    print("1) 저장소 상태 맞추는 중")
    f = run("git", "fetch", "origin", "main")
    if f.returncode != 0:
        print("   !! 깃허브에서 받아오지 못했습니다")
        print(out(f)[:600])
        input("\n엔터를 누르면 닫힙니다...")
        return
    run("git", "reset", "--hard")
    run("git", "checkout", "-B", "main", "origin/main")
    print("   OK")

    print()
    print("2) 파일 넣는 중")
    for rel, b64 in PAYLOAD.items():
        path = os.path.join(ROOT, *rel.split("/"))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fp:
            fp.write(base64.b64decode(b64))
        print("   -", rel)

    print()
    print("3) 깃허브에 올리는 중")
    run("git", "config", "user.name", "wonbi")
    run("git", "config", "user.email", "wonbi@users.noreply.github.com")
    run("git", "add", "-A")
    run("git", "commit", "-m", "영상 생성: 한글 폰트 경로 자동 탐색")
    p = run("git", "push", "-u", "origin", "main")
    if p.returncode != 0:
        run("git", "pull", "--rebase", "--autostash")
        p = run("git", "push", "-u", "origin", "main")

    if p.returncode == 0:
        print("   OK 올라갔습니다")
        print()
        print("   영상 28편은 제가 이어서 돌리겠습니다.")
    else:
        print("   !! 실패")
        print(out(p)[:800])
        print("   로그인 창이 떴는지 확인해 보세요 (Alt+Tab)")

    input("\n엔터를 누르면 닫힙니다...")


if __name__ == "__main__":
    main()
